PRINT N'=== B. SCD TYPE 2: khách đổi địa chỉ ===';
GO
/* 3 khách mua cả 2 đợt VÀ có địa chỉ khác nhau giữa 2 đợt (đây là dữ liệu thật của Olist):
     c51a1ea9fa9851c70f89d1178c861150 : 22775 / rio de janeiro / RJ  ->  22795 / rio de janeiro / RJ
     d3f15df5924e63131bcdac6364b6a6fd : 14403 / franca / SP  ->  09930 / diadema / SP
     da5bbfd583efb762f6fda762f1aaf4a9 : 87020 / maringa / PR  ->  86050 / londrina / PR
   Kỳ vọng ở dim_customer: mỗi khách có 2 dòng (cũ end_date có giá trị, mới end_date NULL);
   đơn quý 1 vẫn trỏ customer_key cũ, đơn tháng 4 trỏ customer_key mới. */
-- Trước khi đổi:
SELECT customer_unique_id, customer_zip_code_prefix, customer_city, customer_state, created_at, updated_at
FROM dbo.customer WHERE customer_unique_id IN ('c51a1ea9fa9851c70f89d1178c861150', 'd3f15df5924e63131bcdac6364b6a6fd', 'da5bbfd583efb762f6fda762f1aaf4a9');
UPDATE dbo.customer SET customer_zip_code_prefix = N'22795', customer_city = N'rio de janeiro', customer_state = N'RJ',
       updated_at = SYSDATETIME()
WHERE customer_unique_id = 'c51a1ea9fa9851c70f89d1178c861150';
UPDATE dbo.customer SET customer_zip_code_prefix = N'09930', customer_city = N'diadema', customer_state = N'SP',
       updated_at = SYSDATETIME()
WHERE customer_unique_id = 'd3f15df5924e63131bcdac6364b6a6fd';
UPDATE dbo.customer SET customer_zip_code_prefix = N'86050', customer_city = N'londrina', customer_state = N'PR',
       updated_at = SYSDATETIME()
WHERE customer_unique_id = 'da5bbfd583efb762f6fda762f1aaf4a9';
-- Sau khi đổi:
SELECT customer_unique_id, customer_zip_code_prefix, customer_city, customer_state, created_at, updated_at
FROM dbo.customer WHERE customer_unique_id IN ('c51a1ea9fa9851c70f89d1178c861150', 'd3f15df5924e63131bcdac6364b6a6fd', 'da5bbfd583efb762f6fda762f1aaf4a9');
GO

PRINT N'=== C. SCD TYPE 1: sản phẩm đổi thuộc tính (ghi đè) ===';
GO
/* 0152f69b6cf919bcdaf117aa8c43e5a2 : weight 250 g -> 750 g
   0233dd6f06e23c705ab76dc3ab165837 : length/height/width 20/16/16 cm -> 25/19/18 cm
   02ce467092b184e71d3967d29110adc1 : category moveis_escritorio -> utilidades_domesticas
   Kỳ vọng ở dim_product: cập nhật tại chỗ, product_key KHÔNG đổi, KHÔNG thêm dòng. */
-- Trước khi đổi:
SELECT * FROM dbo.product WHERE product_id IN ('0152f69b6cf919bcdaf117aa8c43e5a2', '0233dd6f06e23c705ab76dc3ab165837', '02ce467092b184e71d3967d29110adc1');
UPDATE dbo.product SET product_weight_g = 750, updated_at = SYSDATETIME() WHERE product_id = '0152f69b6cf919bcdaf117aa8c43e5a2';
UPDATE dbo.product SET product_length_cm = 25, product_height_cm = 19, product_width_cm = 18,
       updated_at = SYSDATETIME() WHERE product_id = '0233dd6f06e23c705ab76dc3ab165837';
UPDATE dbo.product SET product_category_name = 'utilidades_domesticas', updated_at = SYSDATETIME() WHERE product_id = '02ce467092b184e71d3967d29110adc1';
-- Sau khi đổi:
SELECT * FROM dbo.product WHERE product_id IN ('0152f69b6cf919bcdaf117aa8c43e5a2', '0233dd6f06e23c705ab76dc3ab165837', '02ce467092b184e71d3967d29110adc1');
GO

PRINT N'=== D. UPSERT fact_sales: sửa giá / phí vận chuyển của dòng hàng cũ ===';
GO
/* Giả lập việc bên bán hàng sửa sai giá của các dòng hàng đã nhập trước đó:
     00042b26cf59d7ce69dfabb4e55b4fd9 #1 : price 199.90 -> 189.90 ; freight 18.14 -> 18.14
     00125cb692d04887809806618a2a145f #1 : price 109.90 -> 109.90 ; freight 25.51 -> 30.51
     001dbc16dc51075e987543d23a0507c7 #1 : price 69.90 -> 62.91 ; freight 18.00 -> 20.50
   Kỳ vọng ở fact_sales: UPDATE đúng 3 dòng (số dòng fact KHÔNG tăng vì các dòng này),
   customer_key / product_key / date_key của các dòng này giữ nguyên. */
-- Trước khi sửa:
SELECT order_id, order_item_id, price, freight_value, updated_at FROM dbo.order_item WHERE (order_id = '00042b26cf59d7ce69dfabb4e55b4fd9' AND order_item_id = 1) OR (order_id = '00125cb692d04887809806618a2a145f' AND order_item_id = 1) OR (order_id = '001dbc16dc51075e987543d23a0507c7' AND order_item_id = 1);
UPDATE dbo.order_item SET price = 189.90, freight_value = 18.14, updated_at = SYSDATETIME()
WHERE order_id = '00042b26cf59d7ce69dfabb4e55b4fd9' AND order_item_id = 1;
UPDATE dbo.order_item SET price = 109.90, freight_value = 30.51, updated_at = SYSDATETIME()
WHERE order_id = '00125cb692d04887809806618a2a145f' AND order_item_id = 1;
UPDATE dbo.order_item SET price = 62.91, freight_value = 20.50, updated_at = SYSDATETIME()
WHERE order_id = '001dbc16dc51075e987543d23a0507c7' AND order_item_id = 1;
-- Sau khi sửa:
SELECT order_id, order_item_id, price, freight_value, updated_at FROM dbo.order_item WHERE (order_id = '00042b26cf59d7ce69dfabb4e55b4fd9' AND order_item_id = 1) OR (order_id = '00125cb692d04887809806618a2a145f' AND order_item_id = 1) OR (order_id = '001dbc16dc51075e987543d23a0507c7' AND order_item_id = 1);
GO

PRINT N'=== E. Kiểm tra dữ liệu để Lookup đi nhánh "không khớp" ===';
GO
-- Sản phẩm có category NULL hoặc chưa có bản dịch trong product_category (-> dim_product dùng 'Unknown')
SELECT COUNT(*) AS sp_khong_co_ban_dich
FROM dbo.product p
WHERE p.product_category_name IS NULL
   OR NOT EXISTS (SELECT 1 FROM dbo.product_category c WHERE c.product_category_name = p.product_category_name);
GO

SET NOEXEC OFF;
GO
PRINT N'Hoàn tất: đã tạo "dữ liệu thay đổi" ở nguồn. Chạy lại package Master.dtsx để nạp tăng dần.';
GO
SELECT 'customer' AS bang, COUNT(*) AS so_dong, SUM(CASE WHEN updated_at IS NOT NULL THEN 1 ELSE 0 END) AS so_dong_da_sua FROM dbo.customer
UNION ALL SELECT 'product',    COUNT(*), SUM(CASE WHEN updated_at IS NOT NULL THEN 1 ELSE 0 END) FROM dbo.product
UNION ALL SELECT 'orders',     COUNT(*), SUM(CASE WHEN updated_at IS NOT NULL THEN 1 ELSE 0 END) FROM dbo.orders
UNION ALL SELECT 'order_item', COUNT(*), SUM(CASE WHEN updated_at IS NOT NULL THEN 1 ELSE 0 END) FROM dbo.order_item;
GO
